-- 오타는 이렇게 잡는다

@Component
class UnknownKeyChecker implements InitializingBean {
    private final ConfigurableEnvironment env;
    UnknownKeyChecker(ConfigurableEnvironment env) { this.env = env; }

    @Override
    public void afterPropertiesSet() throws Exception {
        var known = readMetadataKeys();          // 7.8절의 도움말 JSON
        var bad = new ArrayList<String>();
        for (PropertySource<?> ps : env.getPropertySources()) {
            if (!(ps instanceof EnumerablePropertySource<?> e)) continue;
            for (String k : e.getPropertyNames())
                if (k.startsWith("study.") && !known.contains(canonical(k)))
                    bad.add(k + "  (" + ps.getName() + ")");
        }
        if (!bad.isEmpty())
            throw new IllegalStateException("모르는 설정 키: " + bad);
    }
}

